    /**
     * @method
     * @name coincheck#fetchOpenOrders
     * @description fetch all unfilled currently open orders
     * @see https://coincheck.com/documents/exchange/api#order-opens
     * @param {string} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch open orders for
     * @param {int} [limit] the maximum number of  open orders structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<java.util.List<io.github.ccxt.types.Order>> fetchOpenOrders(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbol = Helpers.getArg(optionalArgs, 0, null);
            Object since = Helpers.getArg(optionalArgs, 1, null);
            Object limit = Helpers.getArg(optionalArgs, 2, null);
            Object parameters = Helpers.getArg(optionalArgs, 3, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            // Only BTC/JPY is meaningful
            Object market = null;
            if (Helpers.isTrue(!Helpers.isEqual(symbol, null)))
            {
                market = this.market(symbol);
            }
            Object response = (this.privateGetExchangeOrdersOpens(parameters)).join();
            Object rawOrders = this.safeValue(response, "orders", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object parsedOrders = this.parseOrders(rawOrders, market, since, limit);
            Object result = new java.util.ArrayList<Object>(java.util.Arrays.asList());
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(parsedOrders)); i++)
            {
                ((java.util.List<Object>)result).add(this.extend(Helpers.GetValue(parsedOrders, i), new java.util.HashMap<String, Object>() {{
                    put( "status", "open" );
                }}));
            }
            return result;
        }).thenApply(io.github.ccxt.TypedCores::toOrderList);

    }

    public Object parseOrder(Object order, Object... optionalArgs)
    {
        //
        // fetchOpenOrders
        //
        //     {                        id:  202835,
        //                      "order_type": "buy",
        //                            "rate":  26890,
        //                            "pair": "btc_jpy",
        //                  "pending_amount": "0.5527",
        //       "pending_market_buy_amount":  null,
        //                  "stop_loss_rate":  null,
        //                      "created_at": "2015-01-10T05:55:38.000Z" }
        //
        // todo: add formats for fetchOrder, fetchClosedOrders here
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object id = this.safeString(order, "id");
        Object side = this.safeString(order, "order_type");
        Object timestamp = this.parse8601(this.safeString(order, "created_at"));
        Object amount = this.safeString(order, "pending_amount");
        Object remaining = this.safeString(order, "pending_amount");
        Object price = this.safeString(order, "rate");
        Object status = null;
        Object marketId = this.safeString(order, "pair");
        Object symbol = this.safeSymbol(marketId, market, "_");
        return this.safeOrder(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "clientOrderId", null );
            put( "timestamp", timestamp );
            put( "datetime", Coincheck.this.iso8601(timestamp) );
            put( "lastTradeTimestamp", null );
            put( "amount", amount );
            put( "remaining", remaining );
            put( "filled", null );
            put( "side", side );
            put( "type", null );
            put( "timeInForce", null );
            put( "postOnly", null );
            put( "status", status );
            put( "symbol", symbol );
            put( "price", price );
            put( "triggerPrice", null );
            put( "cost", null );
            put( "fee", null );
            put( "info", order );
            put( "average", null );
            put( "trades", null );
        }}, market);
    }

